struct string_buf {
  unsigned long long *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
  int compare(const string_buf &buf) const {
    int i;
    const char *a = reinterpret_cast<const char *>(data);
    const char *b = reinterpret_cast<const char *>(buf.data);
    int cmp_len = (char_length < buf.char_length ? char_length : buf.char_length);
    for (i = 0; i < cmp_len; i++) {
      if (a[i] == b[i]) continue;
      if (b[i] > a[i]) return 1;
      if (b[i] < a[i]) return -1;
    }
    if (char_length == buf.char_length) return 0;
    if (buf.char_length > char_length) return 1;
    return -1;
  }
};

class stringx {
protected:
  char *chars;
  string_buf *my_buf;
  friend bool operator<(const stringx&, const stringx&);
};
inline bool operator<(const stringx& lhs, const stringx& rhs) {
  return (lhs.my_buf->compare(*rhs.my_buf) == 1);
}

class entity;
template<class T1, class T2> struct pair { T1 first; T2 second; };
typedef pair<const stringx, entity *> value_type;

