struct tree {
  _Rb_tree_node_base *_M_header;
  unsigned int _M_node_count;
};

extern "C" iterator tree_insert(tree *, _Rb_tree_node_base *, _Rb_tree_node_base *, const value_type &)
  __asm__("_M_insert__t8_Rb_tree5Z7stringxZt4pair2ZC7stringxZP6entityZt10_Select1st1Zt4pair2ZC7stringxZP6entityZt4less1Z7stringxZt12my_allocator1ZP6entityP18_Rb_tree_node_baseT1RCt4pair2ZC7stringxZP6entity");

iterator tree_insert(tree *self, _Rb_tree_node_base *x_, _Rb_tree_node_base *y_, const value_type& v) {
  node *x = (node *)x_;
  node *y = (node *)y_;
  node *z;
  if (y == (node *)self->_M_header || x != 0 || v.first < y->value_field.first) {
    z = create_node(self, v);
    y->left = z;
    if (y == (node *)self->_M_header) {
      self->_M_header->parent = z;
      self->_M_header->right = z;
    } else if (y == (node *)self->_M_header->left)
      self->_M_header->left = z;
  } else {
    z = create_node(self, v);
    y->right = z;
    if (y == (node *)self->_M_header->right)
      self->_M_header->right = z;
  }
  z->parent = y;
  z->left = 0;
  z->right = 0;
  rebalance(z, self->_M_header->parent);
  ++self->_M_node_count;
  return iterator(z);
}
